mapper.select:
SELECT FROM "conversation_round" r INNER JOIN ( VALUES
(#{boundary.sourceConversationId}, #{boundary.sourceEndRoundNumber})
) AS requested("conversation_id", "round_number") ON requested."conversation_id" = r."conversation_id" AND requested."round_number" = r."round_number"

SELECT , (SELECT COUNT(*) FROM "conversation_turn" turn WHERE turn."round_id" = r."id") AS "turn_count" FROM "conversation_round" r INNER JOIN ( VALUES
(#{boundary.sourceConversationId}, #{boundary.sourceEndRoundNumber})
) AS requested("conversation_id", "round_number") ON requested."conversation_id" = r."conversation_id" AND r."round_number" <= requested."round_number" WHERE r."status" = 'COMPLETED' AND r."deleted" = FALSE ORDER BY r."conversation_id" ASC, r."round_number" ASC

SELECT DISTINCT "conversation_id" FROM "conversation_round" WHERE "conversation_id" IN
#{conversationId}
AND "status" = 'COMPLETED' AND "deleted" = FALSE

mapper.update:
UPDATE "conversation_round" target_round
SET "trace_id" = source_round."trace_id"
FROM "conversation_round" source_round
WHERE source_round."conversation_id" = #{sourceConversationId}
  AND target_round."conversation_id" = #{targetConversationId}
  AND source_round."round_number" = target_round."round_number"
  AND source_round."round_number" <= #{endRoundNumber}
  AND source_round."status" = 'COMPLETED'
  AND source_round."deleted" = FALSE
